     5	/**
     6	 * 주문 상태를 정의하는 Enum
     7	 */
     8	public enum OrderStatus {
     9	    PENDING_PAYMENT, // 결제 대기
    10	    PAYMENT_COMPLETED, // 결제 완료
    11	    PREPARING, // 상품 준비 중
    12	    IN_WAREHOUSE, // 창고 보관 중
    13	    SHIPMENT_STARTED, // 배송 시작
    14	    IN_TRANSIT, // 배송 중
    15	    COMPLETED, // 배송 완료
    16	    REFUND_REQUESTED, // 환불 대기
    17	    REFUNDED; // 환불 완료
    18	
    19	    // 각 상태에서 전이 가능한 다음 상태들을 정의
    20	    private static final Map<OrderStatus, Set<OrderStatus>> ALLOWED_TRANSITIONS = new HashMap<>();
    21	
    22	    static {
    23	        // 상태 전이 규칙 초기화
    24	        ALLOWED_TRANSITIONS.put(PENDING_PAYMENT, Set.of(PAYMENT_COMPLETED, COMPLETED, IN_WAREHOUSE));
    25	        ALLOWED_TRANSITIONS.put(PAYMENT_COMPLETED, Set.of(PREPARING, REFUND_REQUESTED, IN_WAREHOUSE));
    26	        ALLOWED_TRANSITIONS.put(PREPARING, Set.of(IN_WAREHOUSE, SHIPMENT_STARTED));
    27	        ALLOWED_TRANSITIONS.put(IN_WAREHOUSE, Set.of(SHIPMENT_STARTED, COMPLETED));
    28	        ALLOWED_TRANSITIONS.put(SHIPMENT_STARTED, Set.of(IN_TRANSIT));
    29	        ALLOWED_TRANSITIONS.put(IN_TRANSIT, Set.of(COMPLETED));
    30	        ALLOWED_TRANSITIONS.put(REFUND_REQUESTED, Set.of(REFUNDED));
    31	        ALLOWED_TRANSITIONS.put(COMPLETED, Collections.emptySet());
    32	        ALLOWED_TRANSITIONS.put(REFUNDED, Collections.emptySet());
    33	    }
    34	
    35	    /**
    36	     * 현재 상태에서 새 상태로 전이가 가능한지 확인합니다.
    37	     *
    38	     * @param newStatus 전이하려는 새 상태
    39	     * @return 전이 가능 여부
    40	     */
    41	    public boolean canTransitionTo(OrderStatus newStatus) {
    42	        Set<OrderStatus> allowedNextStates = ALLOWED_TRANSITIONS.get(this);
    43	        return allowedNextStates != null && allowedNextStates.contains(newStatus);
    44	    }
    45	
    46	    /**
    47	     * 현재 상태에서 전이 가능한 모든 상태를 반환합니다.
    48	     *
    49	     * @return 전이 가능한 상태 집합
    50	     */
    51	    public Set<OrderStatus> getAllowedNextStates() {
    52	        return Collections.unmodifiableSet(ALLOWED_TRANSITIONS.getOrDefault(this, Collections.emptySet()));
    53	    }
